    if(!path||!project::kVisualBackdrop[0])return false;
    if(!factory&&FAILED(D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED,factory.ReleaseAndGetAddressOf())))return false;
    if(!wicFactory&&FAILED(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(wicFactory.ReleaseAndGetAddressOf()))))return false;
