    const auto properties=D2D1::RenderTargetProperties(D2D1_RENDER_TARGET_TYPE_SOFTWARE,D2D1::PixelFormat(DXGI_FORMAT_B8G8R8A8_UNORM,D2D1_ALPHA_MODE_PREMULTIPLIED),96.f,96.f);
    if(FAILED(factory->CreateWicBitmapRenderTarget(bitmap.Get(),properties,offscreen.GetAddressOf())))return false;
