int NativeView::visualKeyboardNote(int control,float x,float y)const{
    // DOM order paints black keys last; reverse order also gives them hit priority.
    for(auto it=project::kVisualKeys.rbegin();it!=project::kVisualKeys.rend();++it)if(it->control==control&&x>=it->hx&&x<it->hx+it->hw&&y>=it->hy&&y<it->hy+it->hh)return it->pitch;
    return -1;
}
