D2D1_RECT_F NativeView::labelRect(const D2D1_RECT_F&r)const{const float width=std::max(1.f,currentLabelControlRect.right-currentLabelControlRect.left),height=std::max(1.f,r.bottom-r.top),inset=std::clamp(width*.06f,4.f,8.f),verticalShift=12.f-currentLabelGap;const bool center=containsIgnoreCase(currentLabelPosition,"center"),right=containsIgnoreCase(currentLabelPosition,"right");smallFormat->SetTextAlignment(center?DWRITE_TEXT_ALIGNMENT_CENTER:right?DWRITE_TEXT_ALIGNMENT_TRAILING:DWRITE_TEXT_ALIGNMENT_LEADING);const float top=startsWith(currentLabelPosition,"bottom-")?currentLabelControlRect.bottom-height-verticalShift:currentLabelControlRect.top+verticalShift;return D2D1::RectF(currentLabelControlRect.left+inset,top,currentLabelControlRect.right-inset,top+height);}
int NativeView::hitControl(float x,float y)const{for(int i=(int)project::kControls.size()-1;i>=0;--i){const auto*kind=project::kControls[static_cast<size_t>(i)].kind;if(!controlVisible(static_cast<size_t>(i))||equals(kind,"visual")||equals(kind,"text")||equals(kind,"indicator"))continue;auto r=controlRect(i);const auto point=controlPoint(static_cast<size_t>(i),x,y);if(point.x>=r.left&&point.x<=r.right&&point.y>=r.top&&point.y<=r.bottom)return i;}return-1;}
int NativeView::hitPanelChild(float x,float y)const{if(openPanelIndex<0)return-1;for(int i=(int)project::kControls.size()-1;i>=0;--i){const auto*kind=project::kControls[static_cast<size_t>(i)].kind;if(project::kPanelControls[static_cast<size_t>(i)].parentPanelIndex!=openPanelIndex||equals(kind,"visual")||equals(kind,"text")||equals(kind,"indicator"))continue;const auto r=controlRect(static_cast<size_t>(i));const auto point=controlPoint(static_cast<size_t>(i),x,y);if(point.x>=r.left&&point.x<=r.right&&point.y>=r.top&&point.y<=r.bottom)return i;}return-1;}
int NativeView::prismContextSlot(size_t index)const{if((!project::kIsPrismEq&&!project::kHasPrismModule)||index>=project::kControls.size())return-1;const auto*parameter=project::kControls[index].parameter;return equals(parameter,"prism_frequency")?0:equals(parameter,"prism_gain")?1:equals(parameter,"prism_q")?2:-1;}
ParamID NativeView::displayedParameter(size_t index)const{const int slot=prismContextSlot(index);return slot>=0?instrument.prismParameterFor(selectedPrismBand,slot):instrument.parameterForControl(index);}
float NativeView::indicatorValue(size_t index)const{
    if(index>=project::kControls.size())return 0.f;
    const auto&indicator=project::kControls[index];const int sourceIndex=indicator.indicatorSourceIndex;
    if(indicator.samplerGroupIndex>=0){const auto parameter=instrument.parameterForControl(index);return parameter==kNoParamId?indicator.value:static_cast<float>(instrument.getParamNormalized(parameter));}
    if(sourceIndex<0||sourceIndex>=static_cast<int>(project::kControls.size()))return std::clamp(indicator.value,0.f,1.f);
    const auto&source=project::kControls[static_cast<size_t>(sourceIndex)];
    if(equals(source.kind,"panel_button"))return sourceIndex==openPanelIndex?1.f:0.f;
    if(source.midiSequenceIndex>=0)return source.midiSequenceIndex==instrument.livePatternSequenceIndex()?1.f:0.f;
    if(equals(source.kind,"pad"))return source.notePitch==activeNote||instrument.isNoteActive(source.notePitch)?1.f:0.f;
    const auto parameter=displayedParameter(static_cast<size_t>(sourceIndex));const float value=parameter==kNoParamId?source.value:static_cast<float>(instrument.getParamNormalized(parameter));
    if(equals(source.kind,"button")&&equals(source.parameter,"bypass"))return value<.5f?1.f:0.f;return value>=.5f?1.f:0.f;
}
int NativeView::hitPrismBand(float x,float y)const{if(!project::kIsPrismEq&&!project::kHasPrismModule)return-1;for(size_t i=0;i<project::kControls.size();++i)if(equals(project::kControls[i].kind,"spectrum")&&!equals(project::kControls[i].variant,"pure-spectrum")){const auto r=controlRect(i);const auto point=controlPoint(i,x,y);for(int band=4;band>=0;--band)if(instrument.prismBandEnabled(band)){const float gain=band?((instrument.prismBandValue(band,1)-.5f)*24.f):0.f,nx=r.left+(r.right-r.left)*instrument.prismBandValue(band,0),ny=(r.top+r.bottom)*.5f-gain*(r.bottom-r.top)/36.f;if(std::hypot(point.x-nx,point.y-ny)<=12.f)return band;}break;}return-1;}
void NativeView::updatePrismBandFromPoint(int band,float x,float y){for(size_t i=0;i<project::kControls.size();++i)if(equals(project::kControls[i].kind,"spectrum")&&!equals(project::kControls[i].variant,"pure-spectrum")){const auto r=controlRect(i);const auto point=controlPoint(i,x,y);setParameter(instrument.prismParameterFor(band,0),std::clamp((point.x-r.left)/std::max(1.f,r.right-r.left),0.f,1.f));if(band>0)setParameter(instrument.prismParameterFor(band,1),std::clamp(.5f+((r.top+r.bottom)*.5f-point.y)/(r.bottom-r.top)*1.5f,0.f,1.f));break;}}
void NativeView::setParameter(ParamID id,float v){if(id==kNoParamId)return;v=std::clamp(v,0.f,1.f);instrument.beginEdit(id);instrument.setParamNormalized(id,v);instrument.performEdit(id,v);instrument.endEdit(id);}
void NativeView::applyFactoryPreset(int index){if(index<0||index>=static_cast<int>(project::kPresets.size()))return;const auto&p=project::kPresets[static_cast<size_t>(index)];for(int i=0;i<p.valueCount;++i){const auto&value=project::kPresetValues[static_cast<size_t>(p.valueOffset+i)];setParameter(instrument.parameterForControl(static_cast<size_t>(value.controlIndex)),value.value);}for(int i=0;i<p.groupCount;++i){const auto&g=project::kPresetGroups[static_cast<size_t>(p.groupOffset+i)];setParameter(groupParameterId(g.groupIndex,0),g.volume);setParameter(groupParameterId(g.groupIndex,1),g.pan);setParameter(groupParameterId(g.groupIndex,2),g.mute?1.f:0.f);setParameter(groupParameterId(g.groupIndex,3),g.solo?1.f:0.f);}for(int i=0;i<p.moduleCount;++i){const auto&m=project::kPresetModules[static_cast<size_t>(p.moduleOffset+i)];instrument.applyModulePresetValue(static_cast<size_t>(m.moduleIndex),"bypass",m.bypassed?1.f:0.f);instrument.applyModulePresetValue(static_cast<size_t>(m.moduleIndex),"module_mix",m.mix);for(int j=0;j<m.parameterCount;++j){const auto&parameter=project::kPresetModuleParameters[static_cast<size_t>(m.parameterOffset+j)];instrument.applyModulePresetValue(static_cast<size_t>(parameter.moduleIndex),parameter.key,parameter.value);}}selectedMidiSequence=p.midiSequenceIndex;}
